import type { Rolldown } from 'vite';
/**
 * Vite build result types
 */
export type ViteBuildResult = Rolldown.RolldownOutput | Rolldown.RolldownOutput[] | Rolldown.RolldownWatcher;
/**
 * Options for building a Vite config
 */
export interface ViteConfigOptions {
    root: string;
    base: string;
    entryPoint: string;
    tsConfigPath: string;
    sourcemap: boolean | 'inline' | 'hidden';
    minify: boolean;
    enableCodeSplitting: boolean;
    mode: 'production' | 'development';
    plugins?: unknown[];
    onWarning?: ViteWarningHandler;
}
/**
 * Options for building the index.html for Vite output
 */
export interface ViteHtmlOptions {
    appName: string;
    baseUrl: string;
    mainJsBundle: string;
    mainCssBundle?: string;
    injectSdk: boolean;
    sdkUrl?: string;
    agentUrl?: string;
    appId?: string;
    distDir: string;
}
/**
 * Handler for Vite/Rolldown warnings
 */
export type ViteWarningHandler = (warning: Rolldown.RolldownLog) => void;
